void handleTouch() {
  int16_t tx[1], ty[1];
  bool currentPinState = (touch.getPoint(tx, ty, 1) > 0);
  int16_t touchX = currentPinState ? tx[0] : -1;
  int16_t touchY = currentPinState ? ty[0] : -1;
  unsigned long now = millis();

  if (currentPinState && !lastPinState) {
    pressStartTime = now;
    isLongPressHandled = false;
    pressX = touchX;
    pressY = touchY;
    pressInLanguageButton = languageButtonContains(touchX, touchY);
  } else if (currentPinState && lastPinState) {
    if ((now - pressStartTime > LONG_PRESS_TIME) && !isLongPressHandled) {
      if (!pressInLanguageButton) {
        if (currentPage == 0 && !isShaking && !isAngry) {
          currentMood++;
          if (currentMood > MOOD_SUSPICIOUS) currentMood = 0;
          weatherMood = currentMood;
        } else if (currentPage == 1) {
          subPage = (subPage == 1) ? 0 : 1;
        } else if (currentPage == 2) {
          subPage = (subPage == 2) ? 0 : 2;
        }
      }
      isLongPressHandled = true;
    }
  } else if (!currentPinState && lastPinState) {
    if ((now - pressStartTime < LONG_PRESS_TIME) && !isLongPressHandled) {
      if (pressInLanguageButton) {
        currentLanguage = (currentLanguage == LANG_VI) ? LANG_EN : LANG_VI;
        tapCounter = 0;
      } else {
        tapCounter++;
        lastTapTime = now;
      }
    }
  }

  lastPinState = currentPinState;

  if (tapCounter > 0 && now - lastTapTime > DOUBLE_TAP_DELAY) {
    if (tapCounter == 1) {
      if (subPage != 0) {
        subPage = 0;
      } else {
        currentPage++;
        if (currentPage > 2) currentPage = 0;
      }
    }
    tapCounter = 0;
  }
}

