void drawDizzyEye(Eye& e, bool isLeft) {
  int ix = (int)e.x, iy = (int)e.y, iw = (int)e.w, ih = (int)e.h;
  int cx = ix + iw / 2, cy = iy + ih / 2;

  gfx->fillCircle(cx, cy, iw / 2, RGB565_WHITE);

  unsigned long now = millis();
  float angle = (now - shakeStartTime) * 0.025;
  int radius = iw / 3;
  int pupilX = cx + cos(angle) * radius;
  int pupilY = cy + sin(angle) * radius;
  gfx->fillCircle(pupilX, pupilY, 4, RGB565_BLACK);
  gfx->fillCircle(pupilX + 2, pupilY - 2, 1, RGB565_WHITE);

  int pupilX2 = cx - cos(angle) * radius;
  int pupilY2 = cy - sin(angle) * radius;
  gfx->fillCircle(pupilX2, pupilY2, 3, RGB565_BLACK);

  int starOffset = (now / 80) % 4;
  gfx->drawBitmap(28 - starOffset, 55, bmp_dizzy_stars, 16, 16, RGB565_WHITE);
  gfx->drawBitmap(276 + starOffset, 55, bmp_dizzy_stars, 16, 16, RGB565_WHITE);
}

