  gfx->fillRoundRect(ix, iy, iw, ih, 8, RGB565_WHITE);
  int cx = ix + iw / 2, cy = iy + ih / 2;
  int pupilSize = iw / 2.5;
  int px = cx - 2, py = cy;
  gfx->fillRoundRect(px - pupilSize/2, py - pupilSize/2, pupilSize, pupilSize, pupilSize/2, RGB565_BLACK);

  if (isLeft) {
    for (int i = 0; i < 8; i++) gfx->drawLine(ix-2, iy-2+i, ix+iw+2, iy+6+i, RGB565_BLACK);
    gfx->drawBitmap(ix - 12, iy - 6, bmp_angry_mark, 16, 16, RGB565_WHITE);
  } else {
    for (int i = 0; i < 8; i++) gfx->drawLine(ix-2, iy+6+i, ix+iw+2, iy-2+i, RGB565_BLACK);
    gfx->drawBitmap(ix + iw - 4, iy - 6, bmp_angry_mark, 16, 16, RGB565_WHITE);
  }
  for (int i = 0; i < 3; i++) gfx->drawLine(ix+2+i*4, iy+ih-2, ix+6+i*4, iy+ih-6, RGB565_WHITE);
}

void drawNormalEye(Eye& e, bool isLeft) {
  int ix = (int)e.x, iy = (int)e.y, iw = (int)e.w, ih = (int)e.h;
  int r = (iw < 20) ? 3 : 8;
  gfx->fillRoundRect(ix, iy, iw, ih, r, RGB565_WHITE);

  int cx = ix + iw / 2, cy = iy + ih / 2;
  int pw = iw / 2.2, ph = ih / 2.2;
  int px = cx + (int)e.pupilX - pw / 2;
  int py = cy + (int)e.pupilY - ph / 2;
  if (px < ix) px = ix;
  if (px + pw > ix + iw) px = ix + iw - pw;
  if (py < iy) py = iy;
  if (py + ph > iy + ih) py = iy + ih - ph;
  gfx->fillRoundRect(px, py, pw, ph, r / 2, RGB565_BLACK);
  if (iw > 15 && ih > 15) gfx->fillCircle(px + pw - 4, py + 4, 2, RGB565_WHITE);

  if (currentMood == MOOD_HAPPY || currentMood == MOOD_LOVE)
    gfx->fillRect(ix, iy + ih - 10, iw, 12, RGB565_BLACK);
  else if (currentMood == MOOD_SLEEPY)
    gfx->fillRect(ix, iy, iw, ih / 2, RGB565_BLACK);
  else if (currentMood == MOOD_SAD) {
    if (isLeft)
      for (int i = 0; i < 8; i++) gfx->drawLine(ix, iy+i, ix+iw, iy+4+i, RGB565_BLACK);
    else
      for (int i = 0; i < 8; i++) gfx->drawLine(ix, iy+4+i, ix+iw, iy+i, RGB565_BLACK);
  }
}

void drawMouth() {
  int mx = 160, my = 350;

  if (currentMood == MOOD_DIZZY && isShaking) {
    unsigned long now = millis();
    for (int i = -8; i <= 8; i++) {
      int y = my + sin(i * 0.8 + now * 0.03) * 4;
      gfx->drawPixel(mx + i, y, RGB565_WHITE);
    }
    return;
  }
  if (currentMood == MOOD_ANGRY && isAngry) {
    gfx->fillRect(mx - 8, my - 2, 16, 5, RGB565_BLACK);
    for (int i = -5; i <= 5; i += 3) gfx->drawLine(mx+i, my-2, mx+i, my+2, RGB565_WHITE);
    return;
  }

  switch (currentMood) {
    case MOOD_HAPPY:
      for (int i = -6; i <= 6; i++) {
        int y = my - (i * i / 16);
        if (y < my + 2) gfx->drawPixel(mx + i, y, RGB565_WHITE);
      }
      break;
    case MOOD_SAD:
      for (int i = -6; i <= 6; i++) {
        int y = my + 2 + (i * i / 16);
        gfx->drawPixel(mx + i, y, RGB565_WHITE);
      }
      break;
    case MOOD_SURPRISED:
      gfx->fillCircle(mx, my + 1, 3, RGB565_BLACK);
      gfx->drawCircle(mx, my + 1, 3, RGB565_WHITE);
      break;
    case MOOD_SLEEPY:
      gfx->drawLine(mx - 4, my, mx + 4, my, RGB565_WHITE);
      break;
    case MOOD_LOVE:
      gfx->drawBitmap(mx - 6, my - 2, bmp_heart, 12, 12, RGB565_WHITE);
      break;
    default:
      gfx->drawLine(mx - 4, my, mx + 4, my, RGB565_WHITE);
      break;
  }
}

void updateEyePhysics() {
  unsigned long now = millis();
  breathVal = sin(now / 800.0) * 1.5;

  int blinkDelay = (isShaking || isAngry) ? 60 : 120;
  int blinkMin   = (isShaking || isAngry) ? 300 : 2000;
  int blinkMax   = (isShaking || isAngry) ? 800 : 6000;

  if (now > leftEye.nextBlinkTime) {
    leftEye.blinking = rightEye.blinking = true;
    leftEye.lastBlink = now;
    leftEye.nextBlinkTime = now + random(blinkMin, blinkMax);
  }
  if (leftEye.blinking) {
    leftEye.targetH = rightEye.targetH = 2;
    if (now - leftEye.lastBlink > blinkDelay) {
      leftEye.blinking = rightEye.blinking = false;
      leftEye.targetH  = rightEye.targetH  = 32;
    }
  }
  leftEye.update();
  rightEye.update();
}

void drawEmoPage() {
  updateEyePhysics();
  if (currentMood == MOOD_DIZZY && isShaking) {
    drawDizzyEye(leftEye, true);
    drawDizzyEye(rightEye, false);
  } else if (currentMood == MOOD_ANGRY && isAngry) {
    drawAngryEye(leftEye, true);
    drawAngryEye(rightEye, false);
  } else {
    drawNormalEye(leftEye, true);
    drawNormalEye(rightEye, false);
  }
  drawMouth();

  if (!isShaking && !isAngry) {
    if (currentMood == MOOD_LOVE)
      gfx->drawBitmap(145, 55, bmp_heart, 16, 16, RGB565_WHITE);
    else if (currentMood == MOOD_SLEEPY)
      gfx->drawBitmap(270, 55, bmp_zzz, 16, 16, RGB565_WHITE);
  }
  drawLanguageButton();
}

