void playBootAnimation() {
  gfx->setTextColor(RGB565_WHITE);
  int cx = SCREEN_WIDTH / 2, cy = SCREEN_HEIGHT / 2;
  int maxR = 220;
  for (int r = 0; r < maxR; r += 10) {
    gfx->fillScreen(RGB565_BLACK);
    gfx->fillCircle(cx, cy, r, RGB565_WHITE);
    delay(8);
  }
  for (int r = 0; r < maxR; r += 10) {
    gfx->fillScreen(RGB565_BLACK);
    gfx->fillCircle(cx, cy, maxR, RGB565_WHITE);
    gfx->fillCircle(cx, cy, r, RGB565_BLACK);
    delay(8);
  }

  gfx->setFont(u8g2_font_unifont_t_vietnamese1);
  String bootText = "N I M O";
  int16_t x1, y1; uint16_t w, h;
  gfx->getTextBounds(bootText, 0, 0, &x1, &y1, &w, &h);
  gfx->fillScreen(RGB565_BLACK);
  gfx->setCursor((SCREEN_WIDTH - w) / 2, 250);
