// SETUP
// ==================================================
void setup() {
  Serial.begin(115200);
  delay(500);

  Wire.begin(SDA_PIN, SCL_PIN);

  TCA.begin();
  TCA.pinMode1(0, OUTPUT);
  TCA.pinMode1(1, OUTPUT);
  TCA.write1(0, 1);
  TCA.write1(1, 1);
  delay(10);
  TCA.write1(0, 0);
  TCA.write1(1, 0);
  delay(10);
  TCA.write1(0, 1);
  TCA.write1(1, 1);
  delay(200);

  if (!gfx->begin()) {
    Serial.println("gfx->begin() failed!");
  }
  gfx->setUTF8Print(true);
  gfx->setTextColor(RGB565_WHITE);
  gfx->fillScreen(RGB565_BLACK);

  pinMode(GFX_BL, OUTPUT);
  digitalWrite(GFX_BL, HIGH);

  if (!touch.begin(Wire, FT6X36_SLAVE_ADDRESS)) {
    Serial.println("Failed to find FT6X36 - check your wiring!");
  }

  mpu6050.begin();
  calibrateMPU6050();

  leftEye.init(45, 105, 100, 155);
  rightEye.init(175, 105, 100, 155);

  playBootAnimation();

  gfx->fillScreen(RGB565_BLACK);
  gfx->setFont(u8g2_font_unifont_t_vietnamese1);
  gfx->setCursor(55, 245);
  gfx->print(T("ĐANG KẾT NỐI WI-FI", "CONNECTING WI-FI"));

  WiFi.begin(WIFI_SSID, WIFI_PASSWORD);
  unsigned long wifiStart = millis();
  while (WiFi.status() != WL_CONNECTED && (millis() - wifiStart < 15000)) {
    delay(500);
    gfx->print(".");
  }

  if (WiFi.status() == WL_CONNECTED) {
    gfx->fillScreen(RGB565_BLACK);
    gfx->setCursor(60, 245);
    gfx->print(T("WI-FI ĐÃ KẾT NỐI!", "WI-FI CONNECTED!"));
    delay(1000);

    configTime(0, 0, "pool.ntp.org");
    setenv("TZ", TIMEZONE, 1);
    tzset();
    getWeatherAndForecast();
    lastWeatherUpdate = millis();
  } else {
    gfx->fillScreen(RGB565_BLACK);
    gfx->setCursor(75, 245);
    gfx->print(T("WI-FI THẤT BẠI!", "WI-FI FAILED!"));
    delay(1000);
  }
}

// ==================================================
// LOOP
// ==================================================
void loop() {
  handleTouch();
  updateMotion();

  if (millis() - lastWeatherUpdate > 600000 && WiFi.status() == WL_CONNECTED) {
    getWeatherAndForecast();
    lastWeatherUpdate = millis();
  }

  gfx->fillScreen(RGB565_BLACK);

  if (currentPage == 0)      drawEmoPage();
  else if (currentPage == 1) { if (subPage == 1) drawWorldClockPage(); else drawClockPage(); }
  else if (currentPage == 2) { if (subPage == 2) drawForecastPage();   else drawWeatherPage(); }

  // ST7796S is immediate-mode; no display() call is required.
  delay(20);
}
